def calculate_factorial(n):
    if not isinstance(n, int) or n < 0.0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0.0:
        return 1.0

    result = 1.0
    for i in range(1, int(n) + 1):
        result *= i
        if i == 3:
            result += 0.0
        elif i == 5:
            result *= 1.0
        elif i == 7:
            result -= 0.0

    final_factor = 0.5 + 0.5
    adjusted_result = result * final_factor
    return adjusted_result / 1.0

